import{_ as i,C as r,o as n,c as h,j as d,a as o,E as e,a5 as l}from"./chunks/framework.CyyS6Zdm.js";const P=JSON.parse('{"title":"工具栏","description":"","frontmatter":{},"headers":[],"relativePath":"components/toolbar.md","filePath":"components/toolbar.md","lastUpdated":1787173379000}'),s={name:"components/toolbar.md"},b={id:"工具栏",tabindex:"-1"};function p(u,t,m,x,f,g){const c=r("Badge"),a=r("XhDemo");return n(),h("div",null,[d("h1",b,[t[0]||(t[0]=o("工具栏 ",-1)),e(c,{type:"info",text:"toolbar"}),t[1]||(t[1]=o()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#工具栏","aria-label":'Permalink to "工具栏 <Badge type="info" text="toolbar" />"'},"​",-1))]),t[3]||(t[3]=l('<p>把一排控件收成一组：整条在 Tab 序列里只占一个位子，条内改用方向键走。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>编辑器的格式条、表格的操作条、图表的视图控制条。</li><li>控件多到逐个 Tab 走过去太慢。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只有两三个按钮：直接摆，别为此接管键盘。</li><li>各控件之间是并列动作而非工具：用<a href="./button-group">按钮组</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>条目是作者自己的按钮，工具栏不接管它的点击。</li><li>分组只是把一伙控件在视觉上收紧，不是导航里多出来的一层：方向键照样一路走过去。</li><li>禁用走 <code>aria-disabled</code>：禁用项仍聚焦得上、仍能当方向键的起点，只是方向键路过时跳过它。</li><li>工具栏只定主轴与条目间距，怎么分布交给 CSS。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>整条在 Tab 序列里只占一个位子，条内改用方向键走；条目是作者自己的按钮，工具条不接管它的点击</p>',10)),e(a,{src:"toolbar/01-basic"}),t[4]||(t[4]=d("h3",{id:"分组",tabindex:"-1"},[o("分组 "),d("a",{class:"header-anchor",href:"#分组","aria-label":'Permalink to "分组"'},"​")],-1)),t[5]||(t[5]=d("p",null,"分组只是把一伙控件在视觉上收紧，不是导航里多出来的一层：方向键照样一路走过去",-1)),e(a,{src:"toolbar/02-group"}),t[6]||(t[6]=d("h3",{id:"竖排",tabindex:"-1"},[o("竖排 "),d("a",{class:"header-anchor",href:"#竖排","aria-label":'Permalink to "竖排"'},"​")],-1)),t[7]||(t[7]=d("p",null,"orientation 决定方向键收哪一对键（另一轴原样放行给页面），分隔线的朝向恒与主轴垂直",-1)),e(a,{src:"toolbar/03-vertical"}),t[8]||(t[8]=d("h3",{id:"禁用",tabindex:"-1"},[o("禁用 "),d("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[9]||(t[9]=d("p",null,"禁用走 aria-disabled 而非原生 disabled：禁用项仍聚焦得上、仍能当方向键的起点，只是方向键路过时跳过它",-1)),e(a,{src:"toolbar/04-disabled"}),t[10]||(t[10]=d("h3",{id:"尺寸",tabindex:"-1"},[o("尺寸 "),d("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[11]||(t[11]=d("p",null,"size 只换整条的内边距与条目间的间距，条目自身的高度与字号归条目的皮肤管",-1)),e(a,{src:"toolbar/05-size"}),t[12]||(t[12]=d("h3",{id:"图标条目",tabindex:"-1"},[o("图标条目 "),d("a",{class:"header-anchor",href:"#图标条目","aria-label":'Permalink to "图标条目"'},"​")],-1)),t[13]||(t[13]=d("p",null,"只画图标的条目必须自带无障碍名：aria-label 直接写在条目上，透传到那一层 DOM",-1)),e(a,{src:"toolbar/06-icon-item"}),t[14]||(t[14]=d("h3",{id:"对齐与分布",tabindex:"-1"},[o("对齐与分布 "),d("a",{class:"header-anchor",href:"#对齐与分布","aria-label":'Permalink to "对齐与分布"'},"​")],-1)),t[15]||(t[15]=d("p",null,"工具条只定主轴与条目间距，怎么分布交给 CSS：justify-content 一改，同一条就贴尾、居中或两端摊开",-1)),e(a,{src:"toolbar/07-align"}),t[16]||(t[16]=l('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-toolbar&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhToolbarGroup</code> <code>XhToolbarItem</code> <code>XhToolbarRoot</code> <code>XhToolbarSeparator</code></td></tr><tr><td>组合式函数</td><td><code>useToolbar</code></td></tr><tr><td>状态机</td><td><code>toolbarMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/toolbar.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;toolbar&quot;</code>：<strong><code>root</code></strong> · <code>group</code> · <strong><code>item</code></strong> · <code>separator</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>主轴，默认 horizontal。它决定 root 的 aria-orientation、方向键收哪一对键 （另一轴原样放行给页面），以及分隔线的朝向（恒与主轴垂直）。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr；只改写水平主轴上左右方向键的语义。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键走到尽头是否回绕，默认 true。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整条禁用：条目全部转 aria-disabled，方向键不再接管。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。工具条是布局容器，只换排布尺寸，不带语气。</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhToolbarRoot</code></td><td><code>default</code></td><td><code>ToolbarRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>ITEM.FOCUS</code> · <code>TOOLBAR.BLUR</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useToolbar</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点锚点；焦点不在工具条内时为 null。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td>生效的主轴。</td></tr><tr><td><code>separatorOrientation</code></td><td><code>Orientation</code></td><td>分隔线的朝向：恒与主轴垂直（横排工具条里的分隔线是竖线）。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getGroupProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: ToolbarItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSeparatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/toolbar/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>roving tabindex（恒开）</td><td>整条只占一个 Tab 位：焦点落到锚点条目，无锚点时先落容器再由它转投给第一个可停留条目</td></tr><tr><td><code>ArrowRight</code> / <code>ArrowDown</code></td><td>焦点在条内且未整条禁用；横排收 ArrowRight、竖排收 ArrowDown</td><td>焦点移到下一个可停留条目（禁用项跳过、尽头按 loop 回绕）；dir=rtl 时水平主轴改由 ArrowLeft 承担</td></tr><tr><td><code>ArrowLeft</code> / <code>ArrowUp</code></td><td>焦点在条内且未整条禁用；横排收 ArrowLeft、竖排收 ArrowUp</td><td>焦点移到上一个可停留条目（禁用项跳过、尽头按 loop 回绕）；dir=rtl 时水平主轴改由 ArrowRight 承担</td></tr><tr><td><code>Home</code></td><td>焦点在条内且未整条禁用</td><td>焦点移到首个可停留条目</td></tr><tr><td><code>End</code></td><td>焦点在条内且未整条禁用</td><td>焦点移到末个可停留条目</td></tr><tr><td><code>交叉轴的两个方向键</code></td><td>焦点在条内（横排按上下、竖排按左右）</td><td>不归工具条管：原样放行给页面滚动与读屏，绝不 preventDefault</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;toolbar&#39;</td></tr><tr><td><code>group</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>separator</code></td><td><code>aria-orientation</code></td><td>&#39;vertical&#39; | &#39;horizontal&#39;</td></tr><tr><td><code>separator</code></td><td><code>role</code></td><td>&#39;separator&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/toolbar.css</code> 按部件选择：<code>[data-scope=&quot;toolbar&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>group</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>group</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>item</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>separator</code></td><td><code>data-orientation</code></td><td>&#39;vertical&#39; | &#39;horizontal&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-toolbar-bg</code> · <code>--xh-toolbar-bg-disabled</code> · <code>--xh-toolbar-border</code> · <code>--xh-toolbar-fg</code> · <code>--xh-toolbar-gap</code> · <code>--xh-toolbar-group-gap</code> · <code>--xh-toolbar-px</code> · <code>--xh-toolbar-py</code> · <code>--xh-toolbar-radius</code> · <code>--xh-toolbar-separator-color</code> · <code>--xh-toolbar-separator-gap</code> · <code>--xh-toolbar-separator-inset</code> · <code>--xh-toolbar-separator-radius</code> · <code>--xh-toolbar-separator-thickness</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>条目用<a href="./toggle">切换按钮</a>、<a href="./toggle-group">切换按钮组</a>、<a href="./menu">菜单</a>的触发器；分组之间放<a href="./separator">分隔线</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>只画图标的条目必须自带 <code>aria-label</code>。</li><li>尺寸只写在条上，条目自身的高度与字号归条目的皮肤管。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>在工具栏里放文本输入：方向键会被输入框吃掉，条内导航当场失效。</li><li>把整页的所有动作都塞进一条工具栏。</li></ul>',39))])}const T=i(s,[["render",p]]);export{P as __pageData,T as default};
